            Java

    import java.util.*;

public class Main {

    // Function to find K shortest path lengths
    static void findKShortest(int[][] edges, int n, int m,
                              int k)
    {

        // Initialize graph
        List<List<Pair<Integer, Integer> > > g
            = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            g.add(new ArrayList<>());
        }
        for (int i = 0; i < m; i++) {
            // Storing edges
            g.get(edges[i][0])
                .add(new Pair<>(edges[i][1], edges[i][2]));
        }

        // Vector to store distances
        List<List<Integer> > dis = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            dis.add(new ArrayList<>());
            for (int j = 0; j < k; j++) {
                dis.get(i).add(Integer.MAX_VALUE);
            }
        }

        // Initialization of priority queue
        PriorityQueue<Pair<Integer, Integer> > pq
            = new PriorityQueue<>(
                (a, b) -> a.getKey() - b.getKey());
        pq.add(new Pair<>(0, 1));
        dis.get(1).set(0, 0);

        // while pq has elements
        while (!pq.isEmpty()) {
            // Storing the node value
            int u = pq.peek().getValue();

            // Storing the distance value
            int d = pq.peek().getKey();
            pq.poll();
            if (dis.get(u).get(k - 1) < d)
                continue;
            List<Pair<Integer, Integer> > v = g.get(u);

            // Traversing the adjacency list
            for (int i = 0; i < v.size(); i++) {
                int dest = v.get(i).getKey();
                int cost = v.get(i).getValue();

                // Checking for the cost
                if (d + cost < dis.get(dest).get(k - 1)) {
                    dis.get(dest).set(k - 1, d + cost);

                    // Sorting the distances
                    Collections.sort(dis.get(dest));

                    // Pushing elements to priority queue
                    pq.add(new Pair<>(d + cost, dest));
                }
            }
        }

        // Printing K shortest paths
        for (int i = 0; i < k; i++) {
            System.out.print(dis.get(n).get(i) + " ");
        }
    }

    // Driver Code
    public static void main(String[] args)
    {

        // Given Input
        int N = 4, M = 6, K = 3;
        int[][] edges
            = { { 1, 2, 1 }, { 1, 3, 3 }, { 2, 3, 2 },
                { 2, 4, 6 }, { 3, 2, 8 }, { 3, 4, 1 } };

        // Function Call
        findKShortest(edges, N, M, K);
    }

    static class Pair<K, V> {
        private final K key;
        private final V value;

        public Pair(K key, V value)
        {
            this.key = key;
            this.value = value;
        }

        public K getKey() { return key; }

        public V getValue() { return value; }
    }
}
